package com.coffeeshop.service;import com.coffeeshop.dto.EmployeeCommands;import com.coffeeshop.model.EmployeeModels;import com.coffeeshop.repository.EmployeeRepository;import org.junit.jupiter.api.Test;import java.time.LocalDate;import java.util.*;import static org.junit.jupiter.api.Assertions.*;class EmployeeServiceTest{private final Stub repo=new Stub();private final EmployeeService service=new EmployeeService(repo);@Test void validatesAndNormalizesEmployee(){service.saveEmployee(employee(null," E01 "," Ada "," Lovelace ","ACTIVE",null,null));assertEquals("E01",repo.employee.number());assertEquals("Ada",repo.employee.firstName());}@Test void enforcesTerminationConsistency(){assertThrows(IllegalArgumentException.class,()->service.saveEmployee(employee(null,"E","A","B","TERMINATED",null,null)));assertThrows(IllegalArgumentException.class,()->service.saveEmployee(employee(null,"E","A","B","ACTIVE",LocalDate.now(),null)));}@Test void updateRequiresVersion(){assertThrows(IllegalArgumentException.class,()->service.saveEmployee(employee(1L,"E","A","B","ACTIVE",null,null)));}@Test void hashesPasswordAssignsRolesAndClearsInput(){char[]password="123456".toCharArray();service.saveUser(new EmployeeCommands.SaveUser(null,1," admin ",password,true,true,Set.of(1L),null),9);assertTrue(repo.hash.startsWith("$2"));assertArrayEquals(new char[password.length],password);assertEquals("admin",repo.user.username());assertEquals(Set.of(1L),repo.user.roleIds());assertEquals(9,repo.actor);}@Test void clearsPasswordWhenPersistenceFails(){char[]password="123456".toCharArray();repo.failure=new IllegalStateException("save failed");assertThrows(IllegalStateException.class,()->service.saveUser(new EmployeeCommands.SaveUser(null,1,"admin",password,true,true,Set.of(1L),null),9));assertArrayEquals(new char[password.length],password);}@Test void newUserRequiresSixCharacterPasswordAndRole(){IllegalArgumentException error=assertThrows(IllegalArgumentException.class,()->service.saveUser(new EmployeeCommands.SaveUser(null,1,"u","12345".toCharArray(),true,true,Set.of(1L),null),9));assertEquals("Password must contain at least 6 characters.",error.getMessage());assertThrows(IllegalArgumentException.class,()->service.saveUser(new EmployeeCommands.SaveUser(null,1,"user name","123456".toCharArray(),true,true,Set.of(),null),9));}private static EmployeeCommands.SaveEmployee employee(Long id,String no,String first,String last,String status,LocalDate termination,byte[]version){return new EmployeeCommands.SaveEmployee(id,no,first,last,null,null,null,LocalDate.now().minusDays(1),termination,status,true,version);}private static final class Stub implements EmployeeRepository{EmployeeCommands.SaveEmployee employee;EmployeeCommands.SaveUser user;String hash;long actor;RuntimeException failure;public List<EmployeeModels.Employee>find(String s){return List.of();}public List<EmployeeModels.Role>roles(){return List.of();}public long saveEmployee(EmployeeCommands.SaveEmployee q){employee=q;return 1;}public void setEmployeeActive(long id,boolean a,byte[]v){}public void saveUser(EmployeeCommands.SaveUser q,String h,long actor){if(failure!=null)throw failure;user=q;hash=h;this.actor=actor;}}
}
